from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        for symbol in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.AddEquity(symbol, Resolution.Daily)

        self.spy_sma = self.SMA("SPY", 20, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_sma_prev = None

        self.aapl_rsi = self.RSI("AAPL", 14, Resolution.Daily)
        self.aapl_prev_close = None
        self.aapl_red_days = 0

    def OnData(self, data):
        if not all(data.ContainsKey(s) for s in ["SPY", "AAPL", "IBM", "BAC", "AIG"]):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = self.Securities["SPY"].Close
        spy_sma = self.spy_sma.Current.Value
        aapl_close = self.Securities["AAPL"].Close
        aapl_rsi = self.aapl_rsi.Current.Value

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0:
            if (self.spy_prev_close is not None and self.spy_sma_prev is not None and
                self.spy_prev_close >= self.spy_sma_prev and spy_close < spy_sma):
                self.Sell("SPY", spy_qty)

        if spy_qty == 0:
            if (self.spy_prev_close is not None and self.spy_sma_prev is not None and
                self.spy_prev_close <= self.spy_sma_prev and spy_close > spy_sma):
                amount = self.Portfolio.TotalPortfolioValue * 0.40
                qty = int(amount / spy_close)
                if qty > 0:
                    self.Buy("SPY", qty)

        if aapl_qty > 0:
            if aapl_rsi > 60:
                self.Sell("AAPL", aapl_qty)

        if aapl_qty == 0:
            if self.aapl_red_days >= 3:
                if self.Portfolio.Cash >= 20000:
                    qty = int(20000 / aapl_close)
                    self.Buy("AAPL", qty)

        self.spy_prev_close = spy_close
        self.spy_sma_prev = spy_sma
        self.aapl_prev_close = aapl_close

