from QuantConnect.Indicators import RSI

class LeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.close_history = {s: [] for s in self.symbols}

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.aapl_consecutive_red = 0

        self.aapl_rsi = RSI(14)

    def OnData(self, data):
        # Check all symbols have data
        for symbol in self.symbols:
            if symbol not in data or data[symbol] is None:
                return

        # Append closes to history
        for symbol in self.symbols:
            self.close_history[symbol].append(data[symbol].Close)

        # Update RSI indicator
        self.aapl_rsi.Update(data["AAPL"])

        # Update AAPL consecutive red days
        if len(self.close_history["AAPL"]) >= 2:
            if self.close_history["AAPL"][-1] < self.close_history["AAPL"][-2]:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        # Check minimum history before trading
        if len(self.close_history["SPY"]) < 21 or len(self.close_history["AAPL"]) < 15:
            return
        if not self.aapl_rsi.IsReady:
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        # Evaluate sells first
        if self.strategy_a_shares > 0:
            curr_sma = sum(self.close_history["SPY"][-20:]) / 20.0
            prev_close = self.close_history["SPY"][-2]
            curr_close = self.close_history["SPY"][-1]
            prev_sma = sum(self.close_history["SPY"][-21:-1]) / 20.0

            if prev_close >= prev_sma and curr_close < curr_sma:
                self.MarketOrder("SPY", -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder("AAPL", -self.strategy_b_shares)
                self.strategy_b_shares = 0

        # Evaluate buys
        if self.strategy_a_shares == 0:
            curr_sma = sum(self.close_history["SPY"][-20:]) / 20.0
            prev_close = self.close_history["SPY"][-2]
            curr_close = self.close_history["SPY"][-1]
            prev_sma = sum(self.close_history["SPY"][-21:-1]) / 20.0

            if prev_close <= prev_sma and curr_close > curr_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / curr_close)
                if shares > 0:
                    self.MarketOrder("SPY", shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0:
            if self.aapl_consecutive_red >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)
                        self.strategy_b_shares = shares

