        self.prev_close = {}
        self.prev_spy_sma = None
        self.aapl_red_days = 0
        self.indicators_ready = False

    def OnData(self, data):
        if not all(data.ContainsKey(ticker) for ticker in self.tickers):
            return

        if not self.prev_close:
            for ticker in self.tickers:
                self.prev_close[ticker] = data[ticker].Close
            return

        if not self.indicators_ready:
