from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # State for tracking previous values and red days
        self.spy_close_prev = None
        self.spy_sma_prev = None
        self.aapl_close_prev = None
        self.aapl_red_days = 0

        # Indicators
        self.spy_sma = self.SMA(self.symbols["SPY"], 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

    def OnData(self, data):
        # Check if all subscribed tickers have data
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        # Get current prices and holdings
        spy_close = self.Securities[self.symbols["SPY"]].Close
        aapl_close = self.Securities[self.symbols["AAPL"]].Close
        spy_holdings = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_holdings = self.Portfolio[self.symbols["AAPL"]].Quantity

