        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_sma = self.SMA("SPY", 20)
        self.aapl_rsi = self.RSI("AAPL", 14)

        self.spy_shares = 0
        self.aapl_shares = 0

        self.spy_history = []
        self.aapl_history = []

    def OnData(self, data):
        # Check all tickers have data
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if not data.ContainsKey(ticker):
                return

        # Check indicators are ready
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        # Record current values
        self.spy_history.append((data["SPY"].Close, self.spy_sma.Current.Value))
        self.aapl_history.append(data["AAPL"].Close)

        # Maintain history length
        if len(self.spy_history) > 2:
            self.spy_history.pop(0)
        if len(self.aapl_history) > 4:
            self.aapl_history.pop(0)

        # Ensure sufficient history
        if len(self.spy_history) < 2 or len(self.aapl_history) < 4:
            return

        # Evaluate sells first
        if self.spy_shares > 0:
            if self.spy_crosses_below_sma():
                self.Sell("SPY", self.spy_shares)
                self.spy_shares = 0

        if self.aapl_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Sell("AAPL", self.aapl_shares)
                self.aapl_shares = 0

        # Evaluate buys
        if self.spy_shares == 0:
            if self.spy_crosses_above_sma():
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target = portfolio_value * 0.4
                shares = int(target / data["SPY"].Close)
                if shares > 0:
                    self.Buy("SPY", shares)
                    self.spy_shares = shares

        if self.aapl_shares == 0:
            if self.aapl_red_for_3_days():
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / data["AAPL"].Close)
                    if shares > 0:
                        self.Buy("AAPL", shares)
                        self.aapl_shares = shares

    def spy_crosses_above_sma(self):
        prev_close, prev_sma = self.spy_history[-2]
        curr_close, curr_sma = self.spy_history[-1]
        return prev_close <= prev_sma and curr_close > curr_sma

    def spy_crosses_below_sma(self):
        prev_close, prev_sma = self.spy_history[-2]
        curr_close, curr_sma = self.spy_history[-1]
        return prev_close >= prev_sma and curr_close < curr_sma

    def aapl_red_for_3_days(self):
        red_1 = self.aapl_history[-3] < self.aapl_history[-4]
        red_2 = self.aapl_history[-2] < self.aapl_history[-3]
        red_3 = self.aapl_history[-1] < self.aapl_history[-2]
        return red_1 and red_2 and red_3

