        # Evaluate buys
        if self.spy_shares == 0:
            if self.spy_crosses_above_sma():
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target = portfolio_value * 0.4
                shares = int(target / data["SPY"].Close)
                if shares > 0:
                    self.Buy("SPY", shares)
                    self.spy_shares = shares

        if self.aapl_shares == 0:
            if self.aapl_red_for_3_days():
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / data["AAPL"].Close)
                    if shares > 0:
                        self.Buy("AAPL", shares)
                        self.aapl_shares = shares

    def spy_crosses_above_sma(self):
        prev_close, prev_sma = self.spy_history[-2]
        curr_close, curr_sma = self.spy_history[-1]
        return prev_close <= prev_sma and curr_close > curr_sma

    def spy_crosses_below_sma(self):
        prev_close, prev_sma = self.spy_history[-2]
        curr_close, curr_sma = self.spy_history[-1]
        return prev_close >= prev_sma and curr_close < curr_sma

