                if self.prev_spy_close <= self.prev_spy_ma and spy_close > spy_ma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    qty = int(invest_amount / spy_close)
                    if qty > 0:
                        self.Buy(self.symbols["SPY"], qty)

        # Strategy B buy: AAPL red for 3+ days
        if aapl_holdings == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.Buy(self.symbols["AAPL"], qty)

        # Update previous values for next bar
        self.prev_spy_close = spy_close
        self.prev_spy_ma = spy_ma

