    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_lot = 0
        self.spy_prices = []
        self.spy_prev_close = None
        self.spy_ma_period = 20

        self.aapl_lot = 0
        self.aapl_prices = []
        self.aapl_prev_close = None
        self.aapl_rsi_period = 14
        self.aapl_red_streak = 0

    def OnData(self, data):
        if not self.AllDataPresent(data):
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_prices.append(spy_close)
        if len(self.spy_prices) > self.spy_ma_period + 1:
            self.spy_prices.pop(0)

        self.aapl_prices.append(aapl_close)
        if len(self.aapl_prices) > self.aapl_rsi_period + 1:
            self.aapl_prices.pop(0)

        have_spy_ma = len(self.spy_prices) > self.spy_ma_period
        have_aapl_rsi = len(self.aapl_prices) > self.aapl_rsi_period

        if not have_spy_ma or not have_aapl_rsi:
            self.spy_prev_close = spy_close
            self.aapl_prev_close = aapl_close
            return

        spy_ma = sum(self.spy_prices[-self.spy_ma_period:]) / self.spy_ma_period
        spy_ma_prev = sum(self.spy_prices[-self.spy_ma_period-1:-1]) / self.spy_ma_period
        aapl_rsi = self.CalculateRSI(self.aapl_prices[-self.aapl_rsi_period:])

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.spy_lot > 0 and self.spy_prev_close is not None:
            if self.spy_prev_close > spy_ma_prev and spy_close <= spy_ma:
                self.Liquidate("SPY")
                self.spy_lot = 0

        if self.aapl_lot > 0:
            if aapl_rsi > 60:
                self.Liquidate("AAPL")
                self.aapl_lot = 0

        if self.spy_lot == 0 and self.spy_prev_close is not None:
            if self.spy_prev_close <= spy_ma_prev and spy_close > spy_ma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                quantity = int(invest_amount / spy_close)
                if quantity > 0:
                    self.Buy("SPY", quantity)
                    self.spy_lot = quantity

        if self.aapl_lot == 0:
            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    quantity = int(20000 / aapl_close)
                    if quantity > 0:
                        self.Buy("AAPL", quantity)
                        self.aapl_lot = quantity

        self.spy_prev_close = spy_close
        self.aapl_prev_close = aapl_close

    def AllDataPresent(self, data):
        for ticker in self.tickers:
            if ticker not in data:
                return False
        return True

    def CalculateRSI(self, prices):
        if len(prices) < 2:
            return 50

        gains = 0.0
        losses = 0.0
        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / (len(prices) - 1)
        avg_loss = losses / (len(prices) - 1)

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 50.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

