            if self.aapl_red_streak >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    quantity = int(20000 / aapl_close)
                    if quantity > 0:
                        self.Buy("AAPL", quantity)
                        self.aapl_lot = quantity

        self.spy_prev_close = spy_close
        self.aapl_prev_close = aapl_close

    def AllDataPresent(self, data):
        for ticker in self.tickers:
            if ticker not in data:
                return False
        return True

    def CalculateRSI(self, prices):
        if len(prices) < 2:
            return 50

        gains = 0.0
        losses = 0.0
        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / (len(prices) - 1)
        avg_loss = losses / (len(prices) - 1)

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 50.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi
