            self.spy_price_last = spy_price
            self.aapl_price_last = aapl_price
            return

        spy_sma_current = sum(self.spy_closes) / 100
        aapl_rsi = self.calculate_rsi(self.aapl_closes, 14)

        if self.aapl_price_last is not None:
            if aapl_price < self.aapl_price_last:
                self.aapl_red_count += 1
            else:
                self.aapl_red_count = 0

        if self.spy_lot > 0:
            if self.spy_sma_last is not None and self.spy_price_last is not None:
                crosses_below = (self.spy_price_last >= self.spy_sma_last) and (spy_price < spy_sma_current)
                if crosses_below:
                    self.MarketOrder("SPY", -self.spy_lot)
                    self.spy_lot = 0

        if self.aapl_lot > 0:
            if aapl_rsi > 60:
                self.MarketOrder("AAPL", -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0:
            if self.spy_sma_last is not None and self.spy_price_last is not None:
                crosses_above = (self.spy_price_last <= self.spy_sma_last) and (spy_price > spy_sma_current)
                if crosses_above:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.40
                    shares = int(invest_amount / spy_price)
                    if shares > 0:
                        self.MarketOrder("SPY", shares)
                        self.spy_lot = shares

        if self.aapl_lot == 0:
            if self.aapl_red_count >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_price)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)
                        self.aapl_lot = shares

        self.spy_sma_last = spy_sma_current
        self.spy_price_last = spy_price
        self.aapl_price_last = aapl_price

    def calculate_rsi(self, prices, period):
        if prices.Count < period + 1:
            return 50

        prices_list = list(prices)
        prices_list.reverse()

        gains = 0
        losses = 0

        for i in range(period):
            change = prices_list[i] - prices_list[i + 1]
            if change > 0:
                gains += change
            else:
                losses += -change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi
