from collections import deque

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.slot1_symbol = self.symbols["SPY"]
        self.slot1_closes = deque(maxlen=100)

        self.slot2_symbol = self.symbols["AAPL"]
        self.slot2_closes = deque(maxlen=14)
        self.slot2_red_days = 0

        self.prev_close_spy = None
        self.prev_sma_spy = None
        self.prev_close_aapl = None

        self.ready = False

    def OnData(self, data):
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if self.symbols[ticker] not in data:
                return

        current_close_spy = data[self.slot1_symbol].Close
        current_close_aapl = data[self.slot2_symbol].Close

        self.slot1_closes.append(current_close_spy)
        self.slot2_closes.append(current_close_aapl)

        if len(self.slot1_closes) < 100 or len(self.slot2_closes) < 14:
            self.prev_close_spy = current_close_spy
            self.prev_close_aapl = current_close_aapl
            return

        if not self.ready:
            self.ready = True
            self.prev_sma_spy = sum(self.slot1_closes) / len(self.slot1_closes)
            self.prev_close_spy = current_close_spy
            self.prev_close_aapl = current_close_aapl
            return

        current_sma_spy = sum(self.slot1_closes) / len(self.slot1_closes)
        current_rsi_aapl = self.calculate_rsi(self.slot2_closes)

        if current_close_aapl < self.prev_close_aapl:
            self.slot2_red_days += 1
        else:
            self.slot2_red_days = 0

        slot1_position = self.Portfolio[self.slot1_symbol].Quantity
        slot2_position = self.Portfolio[self.slot2_symbol].Quantity

        if slot1_position > 0:
            if self.prev_close_spy >= self.prev_sma_spy and current_close_spy < current_sma_spy:
                self.MarketOrder(self.slot1_symbol, -slot1_position)

        if slot2_position > 0:
            if current_rsi_aapl > 60:
                self.MarketOrder(self.slot2_symbol, -slot2_position)

        if slot1_position == 0:
            if self.prev_close_spy <= self.prev_sma_spy and current_close_spy > current_sma_spy:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / current_close_spy)
                if shares_to_buy > 0:
                    self.MarketOrder(self.slot1_symbol, shares_to_buy)

        if slot2_position == 0:
            if self.slot2_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / current_close_aapl)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.slot2_symbol, shares_to_buy)

        self.prev_close_spy = current_close_spy
        self.prev_close_aapl = current_close_aapl
        self.prev_sma_spy = current_sma_spy

    def calculate_rsi(self, closes):
        if len(closes) < 14:
            return None

        closes_list = list(closes)
        changes = [closes_list[i] - closes_list[i-1] for i in range(1, len(closes_list))]

        gains = sum(c for c in changes if c > 0)
        losses = sum(-c for c in changes if c < 0)

        avg_gain = gains / len(changes)
        avg_loss = losses / len(changes)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

