            self.AddEquity(symbol, Resolution.Daily)

        self.spy_closes = []
        self.aapl_closes = []
        self.aapl_red_days = 0

    def OnData(self, data: Slice) -> None:
        for symbol in self.symbols:
            if symbol not in data:
                return

        spy_close = self.Securities["SPY"].Close
        aapl_close = self.Securities["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) > 100:
            self.spy_closes.pop(0)
        if len(self.aapl_closes) > 14:
            self.aapl_closes.pop(0)

        if len(self.spy_closes) < 100 or len(self.aapl_closes) < 14:
            return

        spy_sma_100 = sum(self.spy_closes) / len(self.spy_closes)
        spy_prev_sma_100 = sum(self.spy_closes[:-1]) / len(self.spy_closes[:-1])
        spy_prev_close = self.spy_closes[-2]

        aapl_rsi_14 = self.CalculateRSI(self.aapl_closes)

        prev_aapl_close = self.aapl_closes[-2]
        if aapl_close < prev_aapl_close:
            self.aapl_red_days += 1
        else:
            self.aapl_red_days = 0

        spy_position = self.Portfolio["SPY"].Quantity

        if spy_position > 0:
            if spy_prev_close >= spy_prev_sma_100 and spy_close < spy_sma_100:
                self.Liquidate("SPY")
                spy_position = 0

        if spy_position == 0:
            if spy_prev_close <= spy_prev_sma_100 and spy_close > spy_sma_100:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.Buy("SPY", shares)

        aapl_position = self.Portfolio["AAPL"].Quantity

        if aapl_position > 0:
            if aapl_rsi_14 > 60:
                self.Liquidate("AAPL")
                aapl_position = 0

        if aapl_position == 0:
            if self.aapl_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy("AAPL", shares)

    def CalculateRSI(self, closes):
        if len(closes) < 14:
            return 0

        gains = 0
        losses = 0

        for i in range(1, 14):
            change = closes[i] - closes[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

