        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.closes = defaultdict(list)
        self.ma100_values = []
        self.rsi14_values = []

        self.aapl_red_count = 0

    def OnData(self, data):
        # Check all tickers have data
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        # Update closes
        for ticker in self.tickers:
            self.closes[ticker].append(data[self.symbols[ticker]].Close)

        # Calculate SPY 100-day MA
        if len(self.closes["SPY"]) >= 100:
            self.ma100_values.append(np.mean(self.closes["SPY"][-100:]))
        else:
            return

        # Calculate AAPL 14-day RSI
        if len(self.closes["AAPL"]) >= 15:
            rsi = self.CalcRSI(self.closes["AAPL"][-14:])
            self.rsi14_values.append(rsi)
        else:
            return

        # Evaluate sells before buys
        self.EvaluateSells(data)
        self.EvaluateBuys(data)

    def CalcRSI(self, prices):
        if len(prices) < 2:
            return 50

        gains = 0
        losses = 0
        for i in range(1, len(prices)):
            change = prices[i] - prices[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / (len(prices) - 1)
        avg_loss = losses / (len(prices) - 1)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

    def EvaluateSells(self, data):
        # Strategy A: SPY crosses below 100-day MA
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_quantity > 0:
            spy_yesterday = self.closes["SPY"][-2]
            spy_today = self.closes["SPY"][-1]
            ma_yesterday = self.ma100_values[-2]
            ma_today = self.ma100_values[-1]

            if spy_yesterday > ma_yesterday and spy_today <= ma_today:
                self.Liquidate(self.symbols["SPY"])

        # Strategy B: AAPL RSI closes above 60
        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_quantity > 0:
            rsi_today = self.rsi14_values[-1]
            if rsi_today > 60:
                self.Liquidate(self.symbols["AAPL"])

    def EvaluateBuys(self, data):
        # Strategy A: SPY crosses above 100-day MA
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_quantity == 0:
            spy_yesterday = self.closes["SPY"][-2]
            spy_today = self.closes["SPY"][-1]
            ma_yesterday = self.ma100_values[-2]
            ma_today = self.ma100_values[-1]

            if spy_yesterday <= ma_yesterday and spy_today > ma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.4
                shares = int(amount / spy_today)
                if shares > 0:
                    self.Buy(self.symbols["SPY"], shares)

        # Strategy B: AAPL red for 3 consecutive days
        aapl_yesterday = self.closes["AAPL"][-2]
        aapl_today = self.closes["AAPL"][-1]

        if aapl_today < aapl_yesterday:
            self.aapl_red_count += 1
        else:
            self.aapl_red_count = 0

        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_quantity == 0:
            if self.aapl_red_count >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_today)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)

